import { writeFile } from 'node:fs/promises';
import { pool } from '../src/db.mjs';
import { searchCompanies, companyProfile } from '../src/research/companiesHouse.mjs';
import { companyNewsCheck } from '../src/research/newsResearch.mjs';
import { regionForPostcode } from '../src/research/region.mjs';

// Seeds the named-account list for the Marwin DC campaign: a first draft for
// Andy to curate, generated by research rather than left blank. Candidates are
// plain data below; a Tavily discovery pass adds any names the news surfaces,
// then each candidate is matched against Companies House and given a one-line
// reason from recent news. Safe to re-run, existing rows are updated not
// duplicated.

const CANDIDATES = [
  // UK data centre developers and operators
  { name: 'Ark Data Centres', type: 'dc_developer' },
  { name: 'VIRTUS Data Centres', type: 'dc_developer' },
  { name: 'Telehouse International', type: 'dc_developer' },
  { name: 'Digital Realty UK', type: 'dc_developer' },
  { name: 'Equinix UK', type: 'dc_developer' },
  { name: 'Global Switch', type: 'dc_developer' },
  { name: 'Kao Data', type: 'dc_developer' },
  { name: 'Vantage Data Centers UK', type: 'dc_developer' },
  { name: 'CyrusOne UK', type: 'dc_developer' },
  { name: 'Stack Infrastructure', type: 'dc_developer' },
  { name: 'Yondr Group', type: 'dc_developer' },
  { name: 'Colt Data Centre Services', type: 'dc_developer' },
  { name: 'Echelon Data Centres', type: 'dc_developer' },
  { name: 'NTT Global Data Centers UK', type: 'dc_developer' },
  { name: 'Pure Data Centres Group', type: 'dc_developer' },
  { name: 'AtlasEdge', type: 'dc_developer' },
  { name: 'Proximity Data Centres', type: 'dc_developer' },
  { name: 'Latos Data Centres', type: 'dc_developer' },
  { name: 'CloudHQ UK', type: 'dc_developer' },
  { name: 'DC01UK', type: 'dc_developer' },
  { name: 'Iron Mountain Data Centers UK', type: 'dc_developer' },
  { name: '4D Data Centres', type: 'dc_developer' },
  { name: 'Datum Datacentres', type: 'dc_developer' },
  { name: 'Custodian Data Centres', type: 'dc_developer' },
  { name: 'Netwise Hosting', type: 'dc_developer' },
  { name: 'Greystoke Land', type: 'dc_developer' },
  { name: 'Segro', type: 'dc_developer' },
  { name: 'Microsoft UK', type: 'end_client' },
  { name: 'Amazon Web Services UK', type: 'end_client' },
  { name: 'Google UK', type: 'end_client' },

  // M&E contractors active in data centre work
  { name: 'NG Bailey', type: 'me_contractor' },
  { name: 'SES Engineering Services', type: 'me_contractor' },
  { name: 'TClarke', type: 'me_contractor' },
  { name: 'Briggs & Forrester', type: 'me_contractor' },
  { name: 'Gratte Brothers', type: 'me_contractor' },
  { name: 'Michael J Lonsdale', type: 'me_contractor' },
  { name: 'JCA Engineering', type: 'me_contractor' },
  { name: 'Kirby Group Engineering', type: 'me_contractor' },
  { name: 'Jones Engineering', type: 'me_contractor' },
  { name: 'Dornan Engineering', type: 'me_contractor' },
  { name: 'Winthrop Technologies', type: 'me_contractor' },
  { name: 'Mercury Engineering', type: 'me_contractor' },
  { name: 'Phoenix ME', type: 'me_contractor' },
  { name: 'John Sisk & Son', type: 'me_contractor' },
  { name: 'Anord Mardix', type: 'me_contractor' },
];

const DISCOVERY_QUERIES = [
  'largest UK data centre developers and operators',
  'UK data centre construction pipeline 2026 developers',
  'M&E contractors UK data centre projects appointed',
];

const norm = (s) => String(s || '').toLowerCase().replace(/\b(ltd|limited|plc|llp|uk|group|holdings)\b/g, '').replace(/[^a-z0-9]/g, '');

// Optional discovery pass: Tavily surfaces recent coverage, Claude extracts
// company names from it. Skipped quietly if the Anthropic key is absent.
async function discoverCandidates() {
  if (!process.env.ANTHROPIC_API_KEY || !process.env.TAVILY_API_KEY) {
    console.log('Discovery pass skipped (needs ANTHROPIC_API_KEY and TAVILY_API_KEY). Using the curated candidates only.');
    return [];
  }
  const snippets = [];
  for (const q of DISCOVERY_QUERIES) {
    try { snippets.push(...(await companyNewsCheck(q)).map(r => `${r.title}: ${r.snippet}`)); }
    catch (e) { console.log(`  discovery query failed: ${String(e.message).slice(0, 100)}`); }
  }
  if (snippets.length === 0) return [];
  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': process.env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: process.env.CLAUDE_MODEL || 'claude-sonnet-4-6',
        max_tokens: 1200,
        messages: [{
          role: 'user',
          content: 'From these news snippets, list UK data centre developers or operators and M&E contractors active in data centre work. Reply with a JSON array only, each item {"name": "...", "type": "dc_developer" or "me_contractor"}. Exclude consultants, agents and publications.\n\n' + snippets.join('\n').slice(0, 8000),
        }],
      }),
    });
    if (!res.ok) throw new Error(`Claude ${res.status}`);
    const json = await res.json();
    const text = (json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
    const match = text.match(/\[[\s\S]*\]/);
    const list = match ? JSON.parse(match[0]) : [];
    return list.filter(c => c?.name && ['dc_developer', 'me_contractor'].includes(c?.type));
  } catch (e) {
    console.log(`  discovery extraction failed, carrying on with curated candidates: ${String(e.message).slice(0, 100)}`);
    return [];
  }
}

const discovered = await discoverCandidates();
const byName = new Map();
for (const c of [...CANDIDATES, ...discovered]) {
  const key = norm(c.name);
  if (key && !byName.has(key)) byName.set(key, c);
}
console.log(`Candidates: ${CANDIDATES.length} curated, ${discovered.length} discovered, ${byName.size} after dedup.`);

const rows = [];
for (const cand of byName.values()) {
  const entry = { name: cand.name, type: cand.type, chNumber: null, postcode: null, region: null, reason: '' };
  try {
    const matches = await searchCompanies(cand.name);
    const best = matches.find(m => m.status === 'active' && (norm(m.name).includes(norm(cand.name)) || norm(cand.name).includes(norm(m.name))));
    if (best) { entry.chNumber = best.chNumber; entry.postcode = best.postcode; entry.name = best.name; }
  } catch (e) { console.log(`  CH search failed for ${cand.name}: ${String(e.message).slice(0, 100)}`); }

  try {
    const news = await companyNewsCheck(cand.name);
    if (news[0]) entry.reason = news[0].title.slice(0, 120);
  } catch { /* news is optional */ }
  if (!entry.reason) entry.reason = 'sector presence, no recent news found';
  entry.region = regionForPostcode(entry.postcode);

  // Reconcile so re-runs are idempotent, including when a previously unmatched
  // account now matches: find by CH number, else by name, update it; else insert.
  let existingId = null;
  if (entry.chNumber) {
    const { rows } = await pool.query(`SELECT id FROM companies WHERE ch_number = $1`, [entry.chNumber]);
    existingId = rows[0]?.id ?? null;
  }
  if (!existingId) {
    const { rows } = await pool.query(`SELECT id FROM companies WHERE lower(name) = lower($1)`, [entry.name]);
    existingId = rows[0]?.id ?? null;
  }
  if (existingId) {
    await pool.query(
      `UPDATE companies SET named_account = true, company_type = $2,
         ch_number = COALESCE($3, ch_number),
         region = COALESCE(region, $4), postcode = COALESCE(postcode, $5), updated_at = now()
       WHERE id = $1`,
      [existingId, entry.type, entry.chNumber, entry.region, entry.postcode]);
  } else {
    await pool.query(
      `INSERT INTO companies (name, ch_number, company_type, region, postcode, named_account, source)
       VALUES ($1, $2, $3, $4, $5, true, 'seed_research')`,
      [entry.name, entry.chNumber, entry.type, entry.region, entry.postcode]);
  }
  if (entry.chNumber) { try { await companyProfile(entry.chNumber); } catch { /* cache is best effort */ } }
  rows.push(entry);
  console.log(`  ${entry.chNumber ? 'matched ' : 'unmatched'} ${entry.name}`);
}

const label = { dc_developer: 'DC developer or operator', me_contractor: 'M&E contractor', end_client: 'End client' };
const section = (type) => rows.filter(r => r.type === type)
  .map(r => `| ${r.name} | ${label[r.type]} | ${r.chNumber || 'unmatched'} | ${r.region || ''} | ${r.reason} |`).join('\n');

const matched = rows.filter(r => r.chNumber).length;
const md = `# Named accounts, first draft

For Andy to curate: strike through anything that does not belong, correct
company types and regions, and add anything missing. Regions come from the
draft postcode table and need the same check. Generated by research on
${new Date().toISOString().slice(0, 10)}; ${rows.length} accounts, ${matched} matched to Companies House.

| Account | Type | CH number | Region | Why included |
| --- | --- | --- | --- | --- |
${section('dc_developer')}
${section('end_client')}
${section('me_contractor')}
`;

await writeFile(new URL('../NAMED_ACCOUNTS_DRAFT.md', import.meta.url), md);
console.log(`\nWrote NAMED_ACCOUNTS_DRAFT.md: ${rows.length} accounts, ${matched} CH-matched, ${rows.length - matched} unmatched.`);
await pool.end();
